from datasets import load_from_disk
import pandas as pd
import numpy as np
from scipy.optimize import curve_fit

ds = load_from_disk("/tmp/parallel_data/train")
df = ds.to_pandas()

def combined_law_3(X, a, alpha, b, beta, c):
    N, K = X
    return c + a * (N ** -alpha) + b * (K ** -beta)

def combined_law_4(X, a, alpha, b, c):
    N, K = X
    # Here maybe b*K^-beta is not right, maybe a N^-alpha + b K^-alpha ?
    return c + a * (N ** -alpha) + b * (K ** -alpha)

def combined_law_5(X, a, alpha, b, c):
    N, K = X
    return c + a * (N ** -alpha) * (1 + b * (K - 1))

def combined_law_6(X, a, alpha, beta, c):
    N, K = X
    # N is total parameters. Maybe the compute is K * N ? No.
    # What if a * N^-alpha * K^-beta + c ?
    return c + a * (N ** -alpha) * (K ** -beta)

def combined_law_7(X, a, alpha, c, d):
    N, K = X
    return c + a * ((N * K) ** -alpha) + d

for group in df['group'].unique():
    subset = df[df['group'] == group]
    N = subset['num_params'].values
    K = subset['parallel_size'].values
    L = subset['loss'].values
    X = (N, K)

    try:
        popt, _ = curve_fit(combined_law_3, X, L, p0=[100, 0.28, 1, 0.1, 0.8], maxfev=100000)
        print(f"Group: {group} - Law 3: a={popt[0]:.4g}, alpha={popt[1]:.4f}, b={popt[2]:.4g}, beta={popt[3]:.4f}, c={popt[4]:.4f}")
        print("  MSE:", np.mean((L - combined_law_3(X, *popt))**2))
    except Exception as e: print("Law 3 failed", e)

    try:
        popt, _ = curve_fit(combined_law_6, X, L, p0=[100, 0.28, 0.1, 0.8], maxfev=100000)
        print(f"Group: {group} - Law 6 (Law 2): a={popt[0]:.4g}, alpha={popt[1]:.4f}, beta={popt[2]:.4f}, c={popt[3]:.4f}")
        print("  MSE:", np.mean((L - combined_law_6(X, *popt))**2))
    except Exception as e: print("Law 6 failed", e)
